begin;
do $$ begin create type public.payment_schedule_type as enum ('deposit','progress','balance','final','other'); exception when duplicate_object then null; end $$; do $$ begin create type public.payment_method as enum ('bank_transfer','wise','alipay','wechat_pay','cash','other'); exception when duplicate_object then null; end $$;
create table public.payment_schedules(id uuid primary key default gen_random_uuid(),organization_id uuid not null,purchase_order_id uuid not null,sequence_number integer not null check(sequence_number>0),payment_type public.payment_schedule_type not null,description text,expected_amount numeric(18,3) not null check(expected_amount>0),currency text not null check(currency~'^[A-Z]{3}$'),percentage numeric(5,2) check(percentage is null or percentage>0 and percentage<=100),due_date date,notes_internal text,archived_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(purchase_order_id,sequence_number),foreign key(purchase_order_id,organization_id) references public.purchase_orders(id,organization_id));
create table public.payment_records(id uuid primary key default gen_random_uuid(),organization_id uuid not null,purchase_order_id uuid not null,payment_schedule_id uuid,supplier_id uuid not null,amount numeric(18,3) not null check(amount>0),currency text not null check(currency~'^[A-Z]{3}$'),paid_at timestamptz not null,payment_method public.payment_method not null,external_reference text,notes_internal text,recorded_by uuid not null references public.profiles(id),archived_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),foreign key(purchase_order_id,organization_id) references public.purchase_orders(id,organization_id),foreign key(payment_schedule_id) references public.payment_schedules(id),foreign key(supplier_id,organization_id) references public.suppliers(id,organization_id));
create trigger payment_schedules_updated before update on public.payment_schedules for each row execute procedure public.set_updated_at();create trigger payment_records_updated before update on public.payment_records for each row execute procedure public.set_updated_at();
create or replace function public.is_payment_manager(org uuid) returns boolean language sql stable security definer set search_path=public as $$select public.has_active_organization_role(org,array['owner','admin','finance']::public.app_role[])$$;create or replace function public.is_payment_reader(org uuid) returns boolean language sql stable security definer set search_path=public as $$select public.has_active_organization_role(org,array['owner','admin','finance','operations','purchasing','inspection']::public.app_role[])$$;
alter table public.payment_schedules enable row level security;alter table public.payment_records enable row level security;revoke all on public.payment_schedules,public.payment_records from anon,authenticated;grant select,insert,update on public.payment_schedules,payment_records to authenticated;create policy "payment schedule read" on public.payment_schedules for select to authenticated using(public.is_payment_reader(organization_id));create policy "payment schedule manage" on public.payment_schedules for insert to authenticated with check(public.is_payment_manager(organization_id));create policy "payment schedule update" on public.payment_schedules for update to authenticated using(public.is_payment_manager(organization_id)) with check(public.is_payment_manager(organization_id));create policy "payment record read" on public.payment_records for select to authenticated using(public.is_payment_reader(organization_id));create policy "payment record manage" on public.payment_records for insert to authenticated with check(public.is_payment_manager(organization_id) and recorded_by=auth.uid());create policy "payment record update" on public.payment_records for update to authenticated using(public.is_payment_manager(organization_id)) with check(public.is_payment_manager(organization_id));
commit;
